import sqlite3

con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)

print("\n7. Views in sqlite_master:")

views = con.execute("select name from sqlite_master where type='view' order by name").fetchall()

if views:
    for (view_name,) in views:
        try:
            count = con.execute(f'select count(*) from "{view_name}"').fetchone()[0]
            print(f"  {view_name}: {count} rows")
        except Exception as e:
            print(f"  {view_name}: ERROR ({e})")
else:
    print("  [NULL: views — examined sqlite_master, no views found]")

con.close()
